def protocol_v1() -> dict[str, Any]:
    """Return a fresh copy of the frozen Layer 5 protocol."""
    value = json.loads(_PROTOCOL_JSON)
    if sha256_json(value) != LAYER5_PROTOCOL_HASH:
        raise RuntimeError("Layer 5 protocol literal hash mismatch")
    return value


def protocol_hash() -> str:
    return LAYER5_PROTOCOL_HASH


